require "rails_helper"

RSpec.describe Timekeeping::Alerts do
  it "fires reference_unavailable just over 1% of a completed window and stays quiet at exactly 1% and under it" do
    now = Time.utc(2026, 5, 1, 12, 10, 0)
    completed_window_start = "2026-05-01T12:05:00Z"
    signals_for = lambda do |writes, unavailable|
      window = {
        "window_start" => completed_window_start, "writes" => writes, "reference_unavailable" => unavailable,
        "stale_generation" => 0, "latency_ms_sum" => 0, "latency_ms_buckets" => { "25" => writes + unavailable }
      }
      Timekeeping::Alerts::Signals.new(
        now:, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {}, write_pause_seconds: 0,
        stale_generation_outside_handoff_by_company: {},
        write_metrics: {
          "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000], "overflow_bucket" => "inf",
          "total_field" => "writes + reference_unavailable",
          "companies" => [{ "company_id" => 7, "windows" => [window] }]
        },
        prepare_refusals_by_company: {}, unexplained_reconciliation_differences_by_company: {},
        financial_snapshot_changes_by_company: {}
      )
    end
    rate_alerts = ->(signals) { described_class.evaluate(signals).select { |alert| alert.name.to_s == "reference_unavailable" } }

    # "`503 reference_unavailable` over 1% of writes for 5 minutes;"
    # The rate divides by writes + reference_unavailable, the body's total_field.
    fired = rate_alerts.call(signals_for.call(197, 2))
    expect(fired.size).to eq(1)
    expect(fired.first.company_id).to eq(7)

    # 1 of 100 is exactly 1%: "over" is strictly greater, so it stays quiet.
    expect(rate_alerts.call(signals_for.call(99, 1))).to be_empty
    # 2 of 200 is also exactly 1%, and 1 of 101 is under it.
    expect(rate_alerts.call(signals_for.call(198, 2))).to be_empty
    expect(rate_alerts.call(signals_for.call(100, 1))).to be_empty
  end
end

