RSpec.describe Timekeeping::Alerts do
  it "fires the p95 latency alert only when the 95th percentile falls in a bucket above 300 ms, reading the bounds from the body" do
    now = Time.utc(2026, 5, 1, 12, 7, 0)
    signals_for = lambda do |bounds, buckets|
      total = buckets.values.sum
      window = {
        "window_start" => "2026-05-01T12:05:00Z", "writes" => total, "reference_unavailable" => 0,
        "stale_generation" => 0, "latency_ms_sum" => 0, "latency_ms_buckets" => buckets
      }
      Timekeeping::Alerts::Signals.new(
        now:, outbox_lag_seconds_by_company: {}, pending_intent_age_seconds_by_company: {}, write_pause_seconds: 0,
        stale_generation_outside_handoff_by_company: {},
        write_metrics: {
          "latency_bucket_bounds_ms" => bounds, "overflow_bucket" => "inf",
          "total_field" => "writes + reference_unavailable",
          "companies" => [{ "company_id" => 21, "windows" => [window] }]
        },
        prepare_refusals_by_company: {}, unexplained_reconciliation_differences_by_company: {},
        financial_snapshot_changes_by_company: {}
      )
    end
    latency_companies = lambda do |signals|
      described_class.evaluate(signals).filter_map { |alert| alert.company_id if alert.name.to_s == "entry_write_p95_latency" }
    end
    default_bounds = [25, 50, 100, 200, 300, 500, 1000, 2500, 5000]

    # "Timekeeping p95 latency for entry writes over 300 ms."
    # The current, unfinished window counts: this rule has no duration.
    expect(latency_companies.call(signals_for.call(default_bounds, { "100" => 95, "300" => 5 }))).to be_empty
    expect(latency_companies.call(signals_for.call(default_bounds, { "300" => 95, "500" => 5 }))).to be_empty
    expect(latency_companies.call(signals_for.call(default_bounds, { "300" => 94, "500" => 6 }))).to eq([21])
    # Bounds that differ from the default prove the evaluator keeps no copy of its own.
    expect(latency_companies.call(signals_for.call([100, 250, 400], { "250" => 94, "400" => 6 }))).to eq([21])
    expect(latency_companies.call(signals_for.call([100, 250, 400], { "250" => 100 }))).to be_empty
  end
end

